<style>.modulo-cabecalho{margin-bottom:24px}.modulo-cabecalho h1{margin:0;color:var(--navy-deep);font-size:26px}.modulo-cabecalho h1 i{color:var(--green);margin-right:8px}.modulo-cabecalho p{margin:6px 0;color:var(--muted)}.config-form{max-width:900px}.config-cartao{background:#fff;border:1px solid var(--border);border-radius:14px;padding:22px;margin-bottom:18px;box-shadow:var(--shadow-sm)}.config-cartao h2{margin:0 0 6px;color:var(--navy-deep);font-size:18px}.config-cartao h2 i{color:var(--green);margin-right:6px}.config-cartao>p{margin:0 0 16px;color:var(--muted);font-size:13px}.config-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.config-grid label{display:grid;gap:6px;font-size:13px;font-weight:700;color:var(--ink)}.config-grid input,.config-grid select{padding:10px;border:1px solid var(--border);border-radius:8px;font:inherit;background:#fff}@media(max-width:650px){.config-grid{grid-template-columns:1fr}}</style>
